// v07: detailed models (FBX + textures in Resources/SevernyModels, made in Blender: MPFB characters, AV-74 / P-9M).
// Materials: assets generated by the editor (Severny > 9) in Resources/SevernyModels/Materials, runtime fallback otherwise.
// Every caller falls back to the old procedural primitives when a model is missing.
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace Severny
{
    public static class ModelLib
    {
        public const string Root = "SevernyModels/";
        public static bool Disabled;   // debug: force procedural fallback
        static readonly Dictionary<string, GameObject> _prefabs = new Dictionary<string, GameObject>();
        static readonly Dictionary<string, Material> _mats = new Dictionary<string, Material>();
        static Dictionary<string, ModelSpecs.Mat> _specs;

        public static GameObject Prefab(string name)
        {
            if (Disabled) return null;
            if (!_prefabs.TryGetValue(name, out var p))
            {
                p = Resources.Load<GameObject>(Root + name);
                if (p == null) Debug.LogWarning("[Severny] model not found: Resources/" + Root + name + " (procedural fallback)");
                _prefabs[name] = p;
            }
            return p;
        }

        public static GameObject Spawn(string name, Transform parent)
        {
            var p = Prefab(name);
            if (p == null) return null;
            var g = Object.Instantiate(p, parent, false);
            g.name = name;
            ApplyMaterials(g);
            return g;
        }

        // Keep the original generated catalog intact; editor remapping and runtime use the same additions.
        public static IEnumerable<ModelSpecs.Mat> MaterialSpecs
        {
            get
            {
                foreach (var spec in ModelSpecs.Mats) yield return spec;
                foreach (var spec in V14WeaponArt.Materials) yield return spec;
            }
        }

        public static bool TrySpec(string key, out ModelSpecs.Mat s)
        {
            if (_specs == null)
            {
                _specs = new Dictionary<string, ModelSpecs.Mat>();
                foreach (var m in MaterialSpecs) _specs[m.key] = m;
            }
            return _specs.TryGetValue(key, out s);
        }

        /// <summary>"M_Suit05", "M_Suit05.001", "M_Suit05 (Instance)" -> "Suit05".</summary>
        public static string KeyOf(string matName)
        {
            if (string.IsNullOrEmpty(matName)) return "";
            string n = matName.Replace(" (Instance)", "");
            int dot = n.LastIndexOf('.');
            if (dot > 0 && n.Length - dot == 4 && char.IsDigit(n[n.Length - 1])) n = n.Substring(0, dot);
            if (n.StartsWith("M_")) n = n.Substring(2);
            return n;
        }

        public static Texture2D Tex(string name) => string.IsNullOrEmpty(name) ? null : Resources.Load<Texture2D>(Root + "Textures/" + name);

        public static Material Mat(string key)
        {
            if (_mats.TryGetValue(key, out var m)) return m;
            m = Resources.Load<Material>(Root + "Materials/M_" + key);
            if (m == null && TrySpec(key, out var s)) { m = GameAssets.NewLitMaterial(); m.name = "M_" + key; Setup(m, s); }
            _mats[key] = m;
            return m;
        }

        public static void ApplyMaterials(GameObject g)
        {
            foreach (var r in g.GetComponentsInChildren<Renderer>(true))
            {
                var sm = r.sharedMaterials; bool ch = false;
                for (int i = 0; i < sm.Length; i++)
                {
                    if (sm[i] == null) continue;
                    var m = Mat(KeyOf(sm[i].name));
                    if (m != null && m != sm[i]) { sm[i] = m; ch = true; }
                }
                if (ch) r.sharedMaterials = sm;
            }
        }

        /// <summary>URP Lit setup shared by the editor material generator and the runtime fallback.</summary>
        public static void Setup(Material m, ModelSpecs.Mat s)
        {
            var bc = Tex(s.bc); var n = Tex(s.n); var ms = Tex(s.ms);
            m.SetColor("_BaseColor", Color.white); m.SetColor("_Color", Color.white);
            if (bc != null) { m.SetTexture("_BaseMap", bc); m.SetTexture("_MainTex", bc); }
            m.SetFloat("_WorkflowMode", 1f);
            if (n != null) { m.SetTexture("_BumpMap", n); m.SetFloat("_BumpScale", 1f); m.EnableKeyword("_NORMALMAP"); }
            else m.DisableKeyword("_NORMALMAP");
            if (ms != null)
            {
                m.SetTexture("_MetallicGlossMap", ms); m.EnableKeyword("_METALLICSPECGLOSSMAP");
                m.SetTexture("_OcclusionMap", ms); m.SetFloat("_OcclusionStrength", 1f); m.EnableKeyword("_OCCLUSIONMAP");
                m.SetFloat("_Smoothness", 1f); m.SetFloat("_Metallic", s.metal ? 1f : 0f);
            }
            else
            {
                m.DisableKeyword("_METALLICSPECGLOSSMAP"); m.DisableKeyword("_OCCLUSIONMAP");
                m.SetFloat("_Smoothness", s.smooth); m.SetFloat("_Metallic", 0f);
            }
            m.SetFloat("_SmoothnessTextureChannel", 0f);
            m.SetFloat("_Surface", 0f);
            if (s.clip)
            {
                m.SetFloat("_AlphaClip", 1f); m.SetFloat("_Cutoff", 0.5f); m.EnableKeyword("_ALPHATEST_ON");
                m.renderQueue = (int)RenderQueue.AlphaTest; m.SetOverrideTag("RenderType", "TransparentCutout");
            }
            else
            {
                m.SetFloat("_AlphaClip", 0f); m.DisableKeyword("_ALPHATEST_ON");
                m.renderQueue = -1; m.SetOverrideTag("RenderType", "Opaque");
            }
            m.SetFloat("_Cull", s.cull ? (float)CullMode.Back : (float)CullMode.Off);
            m.doubleSidedGI = !s.cull;
            m.enableInstancing = true;
        }

        public static Transform FindDeep(Transform t, string name)
        {
            if (t == null) return null;
            if (t.name == name) return t;
            for (int i = 0; i < t.childCount; i++) { var r = FindDeep(t.GetChild(i), name); if (r != null) return r; }
            return null;
        }

        public static Dictionary<string, Transform> Map(Transform root)
        {
            var d = new Dictionary<string, Transform>();
            foreach (var t in root.GetComponentsInChildren<Transform>(true)) if (!d.ContainsKey(t.name)) d[t.name] = t;
            return d;
        }

        public static void Shadows(GameObject g, ShadowCastingMode mode)
        {
            foreach (var r in g.GetComponentsInChildren<Renderer>(true)) r.shadowCastingMode = mode;
        }
    }
}
